{"path": "src/dias_entre.py", "content": "import datetime

def dias_entre(d1, d2):
    try:
        date_format = '%Y-%m-%d'
        date1 = datetime.datetime.strptime(d1, date_format)
        date2 = datetime.datetime.strptime(d2, date_format)
        delta = abs((date2 - date1).days)
        return delta
    except ValueError:
        raise ValueError('Invalid date format or value')
